$ErrorActionPreference = "Continue"
$poke = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$n = (Get-Content (Join-Path $poke "runs\gbc_full_02\actions.jsonl") | Measure-Object -Line).Lines
$rem = 5000 - $n
$prompt = "Continue from exactly where you left off. The game server crashed and was restored from the last checkpoint, so the world may be slightly behind your newest notes (position, level or a few explored tiles). Trust the live screen and coordinates over stale position/level lines in memory, but keep all verified map and route knowledge. This is the action-based dreaming phase: every 50 successful game actions (poke_act or poke_program), poke_act and poke_program will refuse with DREAM DUE. When that happens: review the recent actions from your own context, compare MEMORY.md against what actually happened, correct wrong or stale claims, merge duplicates, then call memory_dream with a summary. Immediately after memory_dream, call read MEMORY.md and check the rewritten notes. Treat absolute claims such as SEALED, NOT FOUND, unreachable or solid as hypotheses: keep them only if the action log supports them, otherwise mark them unverified and test the lead again. Keep playing toward the staged goals until the action budget runs out."
& (Join-Path $poke "run_resume.ps1") -RunName "gbc_full_02" -MemoryMode full -MapMode none -DreamEvery 0 -DreamEveryActions 50 -RemainingActions $rem -State "checkpoint_full_1784" -ServerPort 8766 -Prompt $prompt
